// The camera sensor catalog, console side (plans/support-other-camera-models,
// DESIGN.md section 2 point 2).
//
// `camera-catalog.json` is generated by the backend (`npm run
// contract:generate`) and vendored here; never hand-edit it. This module is
// the ONLY reader of that file: every label, option field, hint and preset
// warning the console shows about a sensor comes through it, so adding a
// sensor to the platform needs no console code.
//
// The compatibility rule every consumer of the file is held to (stated beside
// `CAMERA_CATALOG_SCHEMA_VERSION` in the backend's `camera-catalog/schema.ts`,
// not inside the JSON):
//
//   1. ignore keys this build does not know; refuse a `schemaVersion` it does
//      not know (the catalog is then unusable as a whole);
//   2. an enum member this build does not know (`tier`, `identity`, an OS
//      release, a `nativeAspect`) means "this ENTRY is not usable by this
//      build": it is not offered, never guessed at, and never a parse failure
//      of the whole catalog;
//   3. never write an option value the catalog does not list.
//
// DOM-free on purpose: the frontend vitest has no DOM, so the rules live here
// and the components are thin renderers over them.

import rawCatalog from "@/lib/camera-catalog.json"

/** The one artifact format this build reads. */
export const CAMERA_CATALOG_SCHEMA_VERSION = 1

/** A port declared EMPTY. A value of the namespace, never a catalog id. */
export const CAMERA_SENSOR_NONE = "none"

/** Working value while the catalog is unreadable (the backend uses the same). */
const FALLBACK_MIN_AGENT = "0.2.0"

const KNOWN_TIERS = ["supported", "supported-with-packages"] as const
const KNOWN_IDENTITIES = ["chip-id", "weak", "none"] as const
const KNOWN_OS_RELEASES = ["bookworm", "trixie"] as const
const KNOWN_ASPECTS = ["16:9", "4:3"] as const

/** The shape of a sensor id on the wire (the namespace's own pattern). */
const SENSOR_ID_RE = /^[a-z][a-z0-9]{1,31}$/

export type CameraSensorTier = (typeof KNOWN_TIERS)[number]

/** One per-board parameter a user may set (`clockFrequency`, `linkFrequency`). */
export interface CameraSensorOption {
  key: string
  label: string
  description: string
  unit: string | null
  /** The closed set of values the catalog lists. */
  values: number[]
  /** The overlay's own default: "absent" and "set to this" mean the same line. */
  default: number
}

export interface CameraSensor {
  id: string
  label: string
  tier: CameraSensorTier
  /** First Rust agent version that knows this sensor, or null when not given. */
  minAgent: string | null
  /** False = `rotation=` changes no pixels; the mounting switch is disabled. */
  canFlip: boolean
  options: CameraSensorOption[]
  /** Every name libcamera may report for this sensor (variants included). */
  libcameraNames: string[]
  /** Device-tree node names without the unit address (`imx708` of `imx708@1a`). */
  dtNodeNames: string[]
  unsupportedPresets: { preset: string; reason: string }[]
}

/**
 * A sensor the catalog names but this build cannot offer. Never listed in a
 * select; kept so that an id already stored on a device still gets its label.
 */
export interface UnavailableCameraSensor {
  id: string
  label: string
  /**
   * `planned`: the platform does not support it yet. `newer`: the entry uses a
   * vocabulary this console build does not know (rule 2), so a newer console
   * is needed to offer it.
   */
  why: "planned" | "newer"
}

export interface CameraCatalog {
  /** False = unknown `schemaVersion` or not a catalog at all: nothing is offered. */
  usable: boolean
  catalogVersion: number | null
  /** Selectable sensors, in catalog order. */
  sensors: CameraSensor[]
  /** Named but not selectable here, in catalog order (`newer` before `planned`). */
  unavailable: UnavailableCameraSensor[]
}

const EMPTY_CATALOG: CameraCatalog = {
  usable: false,
  catalogVersion: null,
  sensors: [],
  unavailable: [],
}

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v)

const nonEmptyString = (v: unknown): v is string =>
  typeof v === "string" && v.length > 0

const stringList = (v: unknown): string[] =>
  Array.isArray(v) ? v.filter(nonEmptyString) : []

const finiteNumber = (v: unknown): v is number =>
  typeof v === "number" && Number.isFinite(v)

function parseOption(raw: unknown): CameraSensorOption | null {
  if (!isPlainObject(raw)) return null
  if (!nonEmptyString(raw.key) || !Array.isArray(raw.values)) return null
  const values = raw.values.filter(finiteNumber)
  if (values.length === 0 || !finiteNumber(raw.default)) return null
  return {
    key: raw.key,
    label: nonEmptyString(raw.label) ? raw.label : raw.key,
    description: nonEmptyString(raw.description) ? raw.description : "",
    unit: nonEmptyString(raw.unit) ? raw.unit : null,
    values,
    default: raw.default,
  }
}

/**
 * One `sensors[]` entry. `null` = not an entry at all (no usable id), which is
 * skipped. An entry with an id but a vocabulary this build does not know comes
 * back as `unavailable` (rule 2).
 */
function parseSensor(
  raw: unknown
): { sensor: CameraSensor } | { unavailable: UnavailableCameraSensor } | null {
  if (!isPlainObject(raw)) return null
  const id = raw.id
  // `none` is reserved for an empty port and can never be a catalog entry.
  if (
    !nonEmptyString(id) ||
    !SENSOR_ID_RE.test(id) ||
    id === CAMERA_SENSOR_NONE
  ) {
    return null
  }
  const label = nonEmptyString(raw.label) ? raw.label : id
  const newer = { unavailable: { id, label, why: "newer" as const } }

  if (!(KNOWN_TIERS as readonly unknown[]).includes(raw.tier)) return newer
  if (!(KNOWN_IDENTITIES as readonly unknown[]).includes(raw.identity))
    return newer
  const requires = raw.requires
  if (isPlainObject(requires) && Array.isArray(requires.os)) {
    const known = KNOWN_OS_RELEASES as readonly unknown[]
    if (requires.os.some((os) => !known.includes(os))) return newer
  }
  const info = raw.info
  if (isPlainObject(info) && info.nativeAspect != null) {
    if (!(KNOWN_ASPECTS as readonly unknown[]).includes(info.nativeAspect))
      return newer
  }
  // The one fact the console acts on. An entry that does not say whether the
  // sensor can flip is not one this build can render honestly.
  const overlay = raw.overlay
  if (!isPlainObject(overlay) || typeof overlay.canFlip !== "boolean")
    return newer

  const options: CameraSensorOption[] = []
  if (Array.isArray(raw.options)) {
    for (const entry of raw.options) {
      const option = parseOption(entry)
      // An option this build cannot read would be written wrongly or not at
      // all, so the whole sensor is left to a newer console.
      if (option === null) return newer
      options.push(option)
    }
  }
  const unsupportedPresets: CameraSensor["unsupportedPresets"] = []
  if (Array.isArray(raw.unsupportedPresets)) {
    for (const entry of raw.unsupportedPresets) {
      if (!isPlainObject(entry)) continue
      if (!nonEmptyString(entry.preset) || !nonEmptyString(entry.reason))
        continue
      unsupportedPresets.push({ preset: entry.preset, reason: entry.reason })
    }
  }
  return {
    sensor: {
      id,
      label,
      tier: raw.tier as CameraSensorTier,
      minAgent: parseSemver(raw.minAgent) ? (raw.minAgent as string) : null,
      canFlip: overlay.canFlip,
      options,
      libcameraNames: stringList(raw.libcameraNames),
      dtNodeNames: stringList(raw.dtNodeNames),
      unsupportedPresets,
    },
  }
}

/**
 * Read a catalog document under the compatibility rule above. Takes anything
 * and never throws: a file this build cannot read is an unusable catalog (no
 * sensor offered), not a crashed page.
 */
export function parseCameraCatalog(raw: unknown): CameraCatalog {
  if (!isPlainObject(raw)) return EMPTY_CATALOG
  if (raw.schemaVersion !== CAMERA_CATALOG_SCHEMA_VERSION) return EMPTY_CATALOG
  const sensors: CameraSensor[] = []
  const unavailable: UnavailableCameraSensor[] = []
  const seen = new Set<string>()
  if (Array.isArray(raw.sensors)) {
    for (const entry of raw.sensors) {
      const parsed = parseSensor(entry)
      if (parsed === null) continue
      const id = "sensor" in parsed ? parsed.sensor.id : parsed.unavailable.id
      if (seen.has(id)) continue
      seen.add(id)
      if ("sensor" in parsed) sensors.push(parsed.sensor)
      else unavailable.push(parsed.unavailable)
    }
  }
  if (Array.isArray(raw.planned)) {
    for (const entry of raw.planned) {
      if (!isPlainObject(entry) || !nonEmptyString(entry.id)) continue
      if (seen.has(entry.id) || entry.id === CAMERA_SENSOR_NONE) continue
      seen.add(entry.id)
      unavailable.push({
        id: entry.id,
        label: nonEmptyString(entry.label) ? entry.label : entry.id,
        why: "planned",
      })
    }
  }
  return {
    usable: true,
    catalogVersion: finiteNumber(raw.catalogVersion)
      ? raw.catalogVersion
      : null,
    sensors,
    unavailable,
  }
}

/** The vendored catalog, parsed once. */
export const CAMERA_CATALOG: CameraCatalog = parseCameraCatalog(rawCatalog)

// ---- lookups ---------------------------------------------------------------
// Every lookup takes whatever it is given (ids and names arrive from stored
// config and from device reports) and finds nothing rather than throwing.

/** A selectable sensor by id. Undefined for `none`, a planned or unknown id. */
export function cameraSensor(
  id: unknown,
  catalog: CameraCatalog = CAMERA_CATALOG
): CameraSensor | undefined {
  if (typeof id !== "string") return undefined
  return catalog.sensors.find((s) => s.id === id)
}

/**
 * The sensor behind a name a DEVICE reported: a libcamera sensor name
 * (`imx708_wide`), a device-tree node with or without its unit address
 * (`imx708@1a`), or a whole libcamera camera path.
 */
export function cameraSensorByDetectedName(
  name: unknown,
  catalog: CameraCatalog = CAMERA_CATALOG
): CameraSensor | undefined {
  if (typeof name !== "string" || name.length === 0) return undefined
  const byLibcamera = catalog.sensors.find((s) =>
    s.libcameraNames.includes(name)
  )
  if (byLibcamera) return byLibcamera
  const node = (name.split("/").pop() ?? "").split("@")[0]
  if (!node) return undefined
  return catalog.sensors.find((s) => s.dtNodeNames.includes(node))
}

/** Display name for a sensor id: the catalog's label, else the id itself. */
export function cameraSensorLabel(
  id: string,
  catalog: CameraCatalog = CAMERA_CATALOG
): string {
  if (id === CAMERA_SENSOR_NONE) return "No camera"
  return (
    cameraSensor(id, catalog)?.label ??
    catalog.unavailable.find((s) => s.id === id)?.label ??
    id
  )
}

/**
 * The short hints beside a sensor in a select: what an operator should know
 * BEFORE choosing it. Deliberately not the catalog's `notes` (whole sentences);
 * a select row has room for a few words.
 */
export function cameraSensorHints(sensor: CameraSensor): string[] {
  const hints: string[] = []
  if (sensor.tier === "supported-with-packages")
    hints.push("needs extra packages")
  if (!sensor.canFlip) hints.push("cannot be rotated")
  return hints
}

/**
 * Why `preset` cannot run on `sensorId`, in the catalog's own sentence, or
 * null when it can. A sensor this build does not know is NOT judged (null):
 * the console only warns about what the catalog actually says.
 */
export function cameraPresetProblem(
  sensorId: unknown,
  preset: unknown,
  catalog: CameraCatalog = CAMERA_CATALOG
): string | null {
  const sensor = cameraSensor(sensorId, catalog)
  if (!sensor || typeof preset !== "string") return null
  return (
    sensor.unsupportedPresets.find((u) => u.preset === preset)?.reason ?? null
  )
}

/** An option value for display: `37.125 MHz`, `2 lanes`, `42`. */
export function formatCameraOptionValue(
  option: CameraSensorOption,
  value: number
): string {
  if (option.unit === "Hz" && Math.abs(value) >= 1_000_000) {
    return `${Number((value / 1_000_000).toFixed(6))} MHz`
  }
  if (option.unit === "Hz" && Math.abs(value) >= 1_000) {
    return `${Number((value / 1_000).toFixed(6))} kHz`
  }
  return option.unit ? `${value} ${option.unit}` : String(value)
}

// ---- agent versions --------------------------------------------------------

/** `1.2.3` (an optional leading `v`, anything after the patch ignored). */
export function parseSemver(value: unknown): [number, number, number] | null {
  if (typeof value !== "string") return null
  const match = /^v?(\d+)\.(\d+)\.(\d+)(?![\d.])/.exec(value.trim())
  if (!match) return null
  return [Number(match[1]), Number(match[2]), Number(match[3])]
}

function compareSemver(
  a: [number, number, number],
  b: [number, number, number]
): number {
  for (let i = 0; i < 3; i++) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1
  }
  return 0
}

/**
 * The first Rust agent version that can act on a sensor choice at all: the
 * lowest `minAgent` in the catalog, which is how the backend computes the
 * version its refusal names. Falls back to the backend's own working value
 * when the catalog gives none.
 */
export function cameraSensorsMinAgent(
  catalog: CameraCatalog = CAMERA_CATALOG
): string {
  let lowest: { text: string; parts: [number, number, number] } | null = null
  for (const sensor of catalog.sensors) {
    const parts = parseSemver(sensor.minAgent)
    if (!parts || sensor.minAgent === null) continue
    if (lowest === null || compareSemver(parts, lowest.parts) < 0) {
      lowest = { text: sensor.minAgent, parts }
    }
  }
  return lowest?.text ?? FALLBACK_MIN_AGENT
}

/**
 * Whether an agent build is KNOWN to predate a sensor. Only a positive answer
 * disables anything: a build this console cannot order (a CI sha, no report)
 * is left to the device, which rejects a sensor its catalog lacks and says so.
 */
export function agentPredatesSensor(
  sensor: CameraSensor,
  agentVersion: string | null | undefined
): boolean {
  const need = parseSemver(sensor.minAgent)
  const have = parseSemver(agentVersion)
  if (!need || !have) return false
  return compareSemver(have, need) < 0
}
